from decimal import Decimal, InvalidOperation
from fractions import Fraction

_CENT = Decimal("0.01")


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    # Exact validation of "at most 2 decimal places" and exact cents
    # without using quantize/multiply under the default 28-digit context
    # (which raises InvalidOperation/rounds for large totals).
    # amount == multiple of 0.01  <=>  d_int * 10**exp is a multiple of 0.01.
    tup = amount.as_tuple()
    if tup.digits:
        d_int = int("".join(map(str, tup.digits)))
    else:
        d_int = 0
    exp = tup.exponent
    if exp >= -2:
        cents = d_int * (10 ** (exp + 2))
    else:
        divisor = 10 ** (-(exp + 2))
        if d_int % divisor != 0:
            raise ValueError("total must have at most 2 decimal places")
        cents = d_int // divisor
    # cents computed above is abs value (d_int ignores sign); amount sign handled below.
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    total_weight = sum(weights, Decimal("0"))
    if total_weight <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    # Exact rational arithmetic for shares to get exact floors/remainders
    # and exact tie-breaks (larger weight, then lower index).
    weights_frac = [Fraction(w) for w in weights]
    total_weight_frac = sum(weights_frac, Fraction(0))
    floors = []
    remainders = []
    for w_frac in weights_frac:
        if w_frac == 0:
            floors.append(0)
            remainders.append(Fraction(0))
        else:
            exact = Fraction(cents) * w_frac / total_weight_frac
            f = exact.numerator // exact.denominator
            floors.append(f)
            remainders.append(exact - f)
    remaining = cents - sum(floors)
    order = sorted(
        (i for i, w in enumerate(weights_frac) if w > 0),
        key=lambda i: (-remainders[i], -weights_frac[i], i),
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts = []
    for floor_cents in floors:
        part = Decimal(floor_cents).scaleb(-2)
        # Ensure exponent is exactly -2 (scaleb on an integer already gives -2).
        # scaleb is exact and does not depend on the context precision,
        # unlike (Decimal(x)/100).quantize(...) which fails for large x.
        if negative and part != 0:
            part = -part
        parts.append(part)
    return parts
